claim/Claim.java:144:    public void setDate(LocalDate date) {
    @Column(nullable = false)
    private boolean stated;

    /** The figure the claim was bound to by its person's last statement; null while unbound or when it had none (n/a). */
    @Column(name = "stated_due", precision = 19, scale = 2)
    private BigDecimal statedDue;

    /** The claim's due-by, fixed when it was created: its date plus the terms of its person's grade in force on its
     *  date then. It does not change when the terms or its date change later. */
    @Column(name = "due_by", nullable = false)
    private LocalDate dueBy;

    /** The number of the settled claim of the same person this correction corrects; null for any other claim. */
    @Column(name = "corrects")
    private String corrects;

        this.lockedBy = lockedBy;
    }

    /** Whether someone other than the user holds the claim's editor open. */
    public boolean isLockedFor(String user) {
        return lockedBy != null && !lockedBy.equals(user);
    }

    /** A copy of the claim as it stood at the end of an earlier date: the status it had then, its due fixed then
     *  (null: not settled then) and its binding then. Only worked out, never saved. */
    public Claim asOf(ClaimStatus status, BigDecimal due, boolean stated, BigDecimal statedDue) {
        Claim then = new Claim(sheetId, personId, amount, date, note, corrects);
        then.id = id;
        then.status = status.name();
        then.number = number;
        then.due = due;
        then.openedBy = openedBy;
        then.dueBy = dueBy;
        then.correctsDate = correctsDate;
        then.listed = listed;
        then.deferredUntil = deferredUntil;
        then.remindedOn = remindedOn;
        then.proofs = proofs;
        then.splitFrom = splitFrom;
        then.lateEntry = lateEntry;
        then.bind(stated, statedDue);
        return then;
    }

    public boolean isLateEntry() {
        return lateEntry;
        String user = AuditUser.decode(userHeader);
        String amountField = amountParam == null ? "" : amountParam.trim();
        if (!AMOUNT.matcher(amountField).matches()) {
            throw new ClaimStatusException("The amount to split off must be a number with up to two decimals.");
        }
        BigDecimal amount = new BigDecimal(amountField).setScale(2);
        if (periods.isClosedOn(claim.getSheetId(), claim.getDueBy())) {
            throw new ClaimStatusException("A claim in a closed period cannot be split.");
        }
        // Lock the sheet first (taking a number locks it), then re-read the claim so a concurrent change is seen.
        boolean perPeriod = sheet.periodNumberingOn();
        if (perPeriod) {
            repository.lockSheet(claim.getSheetId());
        } else {
            repository.takeNextNumber(claim.getSheetId());
        }
        entityManager.refresh(claim);
        if (claim.getStatus() != ClaimStatus.OPEN || claim.isDeferredOn(sheet.getToday())) {
            throw new ClaimStatusException("Only an OPEN claim that is not deferred can be split.");
        }
        if (amount.signum() <= 0 || amount.compareTo(claim.getAmount()) >= 0) {
            throw new ClaimStatusException("The amount to split off must be more than 0.00 and less than the claim's.");
        }
        int terms = people.findById(claim.getPersonId())
                .map(p -> sheet.termsFor(p.getTerms(), grades.gradesOf(p).on(claim.getDate()), claim.getDate())).orElse(0);
        LocalDate dueBy = holidays.nextNonHoliday(claim.getSheetId(), claim.getDate().plusDays(terms));
        String number;
        if (perPeriod) {
            String prefix = periods.findBySheetIdOrderByFromDateAscIdAsc(claim.getSheetId()).stream()
                    .filter(p -> p.contains(dueBy)).map(Period::getName).findFirst().orElse(null);
            String seq = prefix == null ? "X" : "P:" + prefix;
            number = (prefix == null ? "X" : prefix) + "-" + repository.takeNextInSequence(claim.getSheetId(), seq);
        } else {
            number = String.valueOf(repository.lastNumber(claim.getSheetId()));
        }
        claim.setAmount(claim.getAmount().subtract(amount));
